// --- sentencia: const HCFG = {win:120... ---
const HCFG = {win:120, bins:24, lo:0, hi:1.2, margin:0.05};

// --- sentencia: let aBuf = [];... ---
let aBuf = [];

// --- sentencia: let noiseEchoBuf = [];... ---
let noiseEchoBuf = [];

// --- función: shannonEntropy ---
function shannonEntropy(samples, bins, lo, hi){
  if(samples.length < 8) return 0;
  const counts = new Array(bins).fill(0);
  const span = Math.max(1e-9, hi-lo);
  for(const v of samples){
    let idx = Math.floor((v-lo)/span*bins);
    if(idx<0) idx=0; if(idx>=bins) idx=bins-1;
    counts[idx]++;
  }
  const n = samples.length;
  let H = 0;
  for(const c of counts){ if(c>0){ const p=c/n; H -= p*Math.log2(p); } }
  return H; // bits; máximo = log2(bins)
}

// --- función: entropyLocalAbs ---
function entropyLocalAbs(samples, floorSamples, bins, margin){
  if(samples.length < 8) return {H:0, lo:0, hi:0, band:0, floor:0};
  let pLo=Infinity,pHi=-Infinity; for(const v of samples){ if(v<pLo)pLo=v; if(v>pHi)pHi=v; }
  let fLo=Infinity,fHi=-Infinity; for(const v of floorSamples){ if(v<fLo)fLo=v; if(v>fHi)fHi=v; }
  const band = pHi-pLo;
  const floor = (floorSamples.length>=8) ? (fHi-fLo) : 0;
  const center = (pLo+pHi)/2;
  let width = Math.max(band, floor) * (1 + 2*margin);
  if(!(width>0)) width = 1e-9;
  const lo = center - width/2, hi = center + width/2;
  return {H:shannonEntropy(samples, bins, lo, hi), lo, hi, band, floor};
}

// --- función: entropyAtWidth ---
function entropyAtWidth(samples, bins, width){
  if(samples.length < 8 || !(width > 0)) return 0;
  let lo = Infinity, hi = -Infinity;
  for(const v of samples){ if(v < lo) lo = v; if(v > hi) hi = v; }
  const c = (lo + hi) / 2;
  return shannonEntropy(samples, bins, c - width/2, c + width/2);
}

// --- función: entropyRel ---
function entropyRel(samples, bins){
  if(samples.length < 8) return 0;
  let lo=Infinity,hi=-Infinity; for(const v of samples){ if(v<lo)lo=v; if(v>hi)hi=v; }
  if(hi-lo < 1e-9) return 0;
  return shannonEntropy(samples, bins, lo, hi);
}

// --- función: passiveNoiseSample ---
function passiveNoiseSample(){
  // powerBase modulado SOLO por ruido del campo, sin respuesta PTC ni inercia regulatoria
  return state.powerBase + (rngEco()-0.5)*state.noise*10;
}

// --- función: updateBehavioralEntropy ---
function updateBehavioralEntropy(){
  aBuf.push(state.powerLive);
  if(aBuf.length>HCFG.win) aBuf.shift();
  noiseEchoBuf.push(passiveNoiseSample());
  if(noiseEchoBuf.length>HCFG.win) noiseEchoBuf.shift();
  // dos escalas en paralelo (v5) sobre la ventana viva, con calibración local (v7):
  const la = entropyLocalAbs(aBuf, noiseEchoBuf, HCFG.bins, HCFG.margin); // ABS local, suelo=ruido
  state.H_at    = la.H;                              // amplitud calibrada al sistema
  state.H_rel   = entropyRel(aBuf, HCFG.bins);       // forma (ciega al silencio)
  state.H_noise = entropyAtWidth(noiseEchoBuf, HCFG.bins, la.hi-la.lo); // piso: misma ANCHURA de regla, centrada en el propio ruido (v7.1)
  state.absBand = la.band; state.absFloor = la.floor;
}

// --- sentencia: const DAISY_S = 9.17e5,... ---
const DAISY_S = 9.17e5, DAISY_SIGMA = 5.6704e-5, DAISY_K = DAISY_S/DAISY_SIGMA;

// --- función: temperaturaPlanetariaReal ---
function temperaturaPlanetariaReal(absorbido){
  return Math.pow(DAISY_K*Math.max(absorbido,1e-9), 0.25) - 273;
}

// --- función: abioticTf ---
function abioticTf(lum){
  // CURVA DEL PLANETA ESTÉRIL (v7.2, física real desde v7.7). Es la
  // temperatura que tendría este mismo planeta sin floración: sin ella el
  // albedo es el del suelo desnudo, y no existe el empuje regulatorio
  // 8.2*powerLive. Misma forma que targetTf en computeFloracion, con
  // albedo fijo.
  // ANTES devolvía tOpt constante: la huella biótica no era una huella sino
  // la desviación |Tf − tOpt|. Corregido tras la auditoría del 25-jul-2026.
  // v7.9 — acepta luminosidad EFECTIVA (con estación aplicada) para que la
  // huella biótica siga siendo válida cuando las estaciones están activas;
  // sin argumento usa state.luminosity, igual que siempre.
  if(lum===undefined) lum=state.luminosity;
  return temperaturaPlanetariaReal(lum*(1 - state.albedoSueloDesnudo));
}

