// --- función: pseudoNoise ---
function pseudoNoise(x,y,t){const s=Math.sin(x*12.9898+y*78.233+t*0.021)*43758.5453;return(s-Math.floor(s))*2-1}

// --- función: evolveField ---
function evolveField(albedo){const next=field.map(r=>r.slice());const cx=gridSize/2,cy=gridSize/2;for(let y=0;y<gridSize;y++)for(let x=0;x<gridSize;x++){const dx=(x-cx)/cx,dy=(y-cy)/cy,r=Math.sqrt(dx*dx+dy*dy),edge=gauss(r,0.72,0.11+state.band*0.03),daisyMix=state.floracion*(1-r)+state.gyriosomus*r,noise=(pseudoNoise(x,y,state.tick+state.seed*1013.9)-0.5)*state.noise*16,target=state.Tf+edge*state.delta*1.8+daisyMix*1.2-albedo*1.8+noise,smooth=clamp(0.05+state.sigma*0.01,0.04,0.16);let n=0,c=0;for(let oy=-1;oy<=1;oy++)for(let ox=-1;ox<=1;ox++){const nx=x+ox,ny=y+oy;if(nx>=0&&nx<gridSize&&ny>=0&&ny<gridSize){n+=field[ny][nx];c++}}next[y][x]=lerp(n/c,target,smooth)}field=next}

// --- función: computeDeltaStruct ---
function computeDeltaStruct(field){let sum=0,sumSq=0,n=0;for(let y=0;y<field.length;y++)for(let x=0;x<field[0].length;x++){const v=field[y][x];sum+=v;sumSq+=v*v;n++}const mean=sum/n;return Math.sqrt(Math.max(sumSq/n-mean*mean,0))}

// --- función: computeCoupling ---
function computeCoupling(Tf,targetTf){const diff=Math.abs(Tf-targetTf);return Math.max(0,1-diff/8.0)}

