// --- función: clasificarCierre ---
function clasificarCierre(){
  const _semanaActual = semanaDelAnioReal(diaCalendarioActual());
  const ratioLF = state.LF / (KAPPA_CANONICOS ? KAPPA_LF_INFIMO : KAPPA_LF_POR_SEMANA[_semanaActual]);
  // Δ_struct: condición de existencia de diferencia (Δ_struct > 0), no de
  // comparación contra un percentil -- ver el bloque de κ_Δ más arriba.
  // Infinity = "no restringe": min(ratioLF, Infinity) deja la activación
  // gobernada por LF, que es lo que la Teoría pide. Si la diferencia se borrara
  // del todo (homogeneización) el ratio cae a 0 y el sistema deja de estar activo.
  const ratioDelta = KAPPA_DELTA_CANONICO
    ? (state.deltaStruct > 0 ? Infinity : 0)
    : state.deltaStruct / (KAPPA_CANONICOS ? KAPPA_DELTA_INFIMO : KAPPA_DELTA_POR_SEMANA[_semanaActual]);
  const ratioA = state.A_sys_env / (KAPPA_CANONICOS ? KAPPA_V_CANONICO : KAPPA_V_POR_SEMANA[_semanaActual]);
  // C-N2.8.5 -- 0 < |e_R| < κ_O son DOS cotas.
  // Cota superior (colapso): ratioE = 1 justo en κ_O, y sube con el margen.
  // Cota inferior (sin señal correctora): err = 0 NO es viable por muy holgada
  // que esté la de arriba. No lleva número inventado -- el canon dice "> 0".
  let ratioE = 2 - (state.err / (KAPPA_CANONICOS ? KAPPA_O_CANONICO : KAPPA_O_POR_SEMANA[_semanaActual]));
  if (ERR_COTA_INFERIOR && !(state.err > 0)) ratioE = 0;
  const xRatio = Math.min(ratioLF, ratioDelta);   // ≥1 ⇔ ACTIVACIÓN
  const yRatio = Math.min(ratioA, ratioE);        // ≥1 ⇔ VIABILIDAD
  const activo = xRatio >= 1, viable = yRatio >= 1;
  let zona;
  if (viable && activo) zona = 'JARDIN_FERTIL';
  else if (viable && !activo) zona = 'CIERRE';
  else if (!viable && activo) zona = 'SELVA_HOSTIL';
  else zona = 'COLAPSO';
  // signo por zona: activo→+X, quieto→-X; viable→+Y, no-viable→-Y.
  // En reposo (todo en 0) xRatio=yRatio=0 → signedX=signedY=0 SIEMPRE, sin
  // importar el signo (0×±1=0): el marcador arranca exacto en el centro.
  const signedX = activo ? xRatio : -xRatio;
  const signedY = viable ? yRatio : -yRatio;
  return { zona, signedX, signedY, xRatio, yRatio };
}

