// --- función: registrarSaturacion ---
function registrarSaturacion(){
  const sat=(state.ptcOut>=1.2-1e-9||state.ptcOut<=0.05+1e-9)?1:0;
  satBuf.push(sat); if(satBuf.length>SAT_VENTANA) satBuf.shift();
  let n=0; for(const b of satBuf) n+=b;
  state.satFrac = satBuf.length ? n/satBuf.length : 0;
  state.satCiego = state.satFrac > SAT_UMBRAL;
  return sat;
}

