// --- función: diaCalendarioActual ---
function diaCalendarioActual(){
  return Math.min(Math.floor(state.tick / TICKS_POR_DIA), TOPE_DIA_CALENDARIO);
}

// --- función: fechaDesdeDiaCalendario ---
function fechaDesdeDiaCalendario(dia){
  const anio = ANIO_CERO + Math.floor(dia / DIAS_POR_ANIO_CAL);
  let resto = dia % DIAS_POR_ANIO_CAL;
  let mes = 0;
  while (resto >= DIAS_POR_MES_CAL[mes]) { resto -= DIAS_POR_MES_CAL[mes]; mes++; }
  return { anio, mes, diaMes: resto + 1 }; // diaMes 1-based
}

// --- función: formatearFechaCalendario ---
function formatearFechaCalendario(dia){
  const f = fechaDesdeDiaCalendario(dia);
  return f.diaMes + '-' + MES_ABREV_CAL[f.mes] + '-' + f.anio;
}

// --- función: actualizarLluviaDesdeCalendario ---
function actualizarLluviaDesdeCalendario(){
  const anio = fechaDesdeDiaCalendario(diaCalendarioActual()).anio;
  const valor = picoMensualAnio(anio);
  state.sinDatoLluvia = (valor === null || valor === undefined);
  state.lluviaAcumulada = state.sinDatoLluvia ? 0 : valor;
  if (els.lluvia) els.lluvia.value = String(state.lluviaAcumulada);
  if (els.lluviaVal) els.lluviaVal.textContent = state.lluviaAcumulada.toFixed(0);
  const badge = $('lluviaSinDato');
  if (badge) {
    badge.hidden = !state.sinDatoLluvia;
    const spanAnio = $('anioSinDato');
    if (spanAnio) spanAnio.textContent = String(anio);
  }
}

// --- función: claveFechaDiaria ---
function claveFechaDiaria(dia){
  const f = fechaDesdeDiaCalendario(dia);
  const pad = (n) => String(n).padStart(2, '0');
  return f.anio + '-' + pad(f.mes + 1) + '-' + pad(f.diaMes);
}

// --- función: actualizarLluviaDesdeCalendarioDiario ---
function actualizarLluviaDesdeCalendarioDiario(dia){
  const VENTANA_DIAS = 30, MIN_DIAS_CON_DATO = 15;
  let suma = 0, diasConDato = 0;
  for (let d = Math.max(0, dia - VENTANA_DIAS + 1); d <= dia; d++) {
    const v = LLUVIA_DIARIA_1966_2017[claveFechaDiaria(d)];
    if (v !== null && v !== undefined) { suma += v; diasConDato++; }
  }
  state.sinDatoLluvia = (diasConDato < MIN_DIAS_CON_DATO);
  state.lluviaAcumulada = state.sinDatoLluvia ? 0 : suma;
  if (els.lluvia) els.lluvia.value = String(state.lluviaAcumulada);
  if (els.lluviaVal) els.lluviaVal.textContent = state.lluviaAcumulada.toFixed(0);
  const badge = $('lluviaSinDato');
  if (badge) {
    badge.hidden = !state.sinDatoLluvia;
    const spanAnio = $('anioSinDato');
    if (spanAnio) spanAnio.textContent = String(fechaDesdeDiaCalendario(dia).anio);
  }
}

// --- sentencia: const LLUVIA_DIARIA_FIN_DIA = (function(... ---
const LLUVIA_DIARIA_FIN_DIA = (function(){
  let offset = 0;
  for (let m = 0; m < 4; m++) offset += DIAS_POR_MES_CAL[m]; // ene..abr completos
  offset += 31 - 1; // hasta el 31 de mayo (0-based dentro del mes)
  return diaDesdeAnio(2017, offset);
})();

// --- función: enTramoLluviaDiaria ---
function enTramoLluviaDiaria(dia){
  return typeof LLUVIA_DIARIA_1966_2017 !== 'undefined' && dia <= LLUVIA_DIARIA_FIN_DIA;
}

// --- función: actualizarLluviaDesdeCalendarioMensual ---
function actualizarLluviaDesdeCalendarioMensual(dia){
  const MESES_VENTANA = 2;
  const f = fechaDesdeDiaCalendario(dia);
  let mes = f.mes, anio = f.anio, suma = 0, mesesConDato = 0;
  for (let i = 0; i < MESES_VENTANA; i++) {
    const v = valorMesReal(anio, mes);
    if (v !== null && v !== undefined) { suma += v; mesesConDato++; }
    mes--; if (mes < 0) { mes = 11; anio--; }
  }
  state.sinDatoLluvia = (mesesConDato === 0);
  state.lluviaAcumulada = state.sinDatoLluvia ? 0 : (suma / mesesConDato);
  if (els.lluvia) els.lluvia.value = String(state.lluviaAcumulada);
  if (els.lluviaVal) els.lluviaVal.textContent = state.lluviaAcumulada.toFixed(0);
  const badge = $('lluviaSinDato');
  if (badge) {
    badge.hidden = !state.sinDatoLluvia;
    const spanAnio = $('anioSinDato');
    if (spanAnio) spanAnio.textContent = String(f.anio);
  }
}

// --- sentencia: const DURACION_FLORACION_DIAS = 166;... ---
const DURACION_FLORACION_DIAS = 166;

// --- sentencia: const EMP_B0 = -1.2123, EMP_B1 = 0.0185;... ---
const EMP_B0 = -1.2123, EMP_B1 = 0.0185;

// --- sentencia: const KAPPA_REGULACION_INTERGLACIAL = 9.... ---
const KAPPA_REGULACION_INTERGLACIAL = 9.4;

// --- sentencia: let PTC_REEMPLAZO_MODO = 'B';... ---
let PTC_REEMPLAZO_MODO = 'B';

// --- sentencia: const VELOCIDAD_FLORACION_MAX_TEORICA = ... ---
const VELOCIDAD_FLORACION_MAX_TEORICA = 0.9/(90*TICKS_POR_DIA);

// --- función: objetivoFloracionEmpirico ---
function objetivoFloracionEmpirico(lluvia){
  // Piso mecanico duro real (Chavez et al. 2019): sin al menos el umbral de
  // germinacion en un solo pulso, no hay floracion, sin importar lo que
  // diga el ajuste anual.
  if(lluvia < state.umbralGerminacion) return 0;
  const logit = EMP_B0 + EMP_B1*lluvia;
  return (1/(1+Math.exp(-logit))) * 0.9;
}

// --- función: computeFloracion ---
function computeFloracion(lum){
  if(lum===undefined) lum=state.luminosity;
  // Gyriosomus NO entra al reparto de suelo ni al albedo -- es un animal que
  // responde a la floracion, no vegetacion que compite por espacio (a
  // diferencia de negras/blancas en Daisyworld, que competian por el mismo
  // suelo). Solo la floracion cubre/descubre terreno.
  const objetivo = objetivoFloracionEmpirico(state.lluviaAcumulada);
  const floracionAntes = state.floracion; // para medir velocidad real de transición, ver PTC_REEMPLAZO_MODO
  // Dos velocidades reales, no una sola inventada: el ASCENSO usa el rezago
  // lluvia-vegetacion medido por He et al. 2017 (~3 meses, 90 dias); el
  // DECLIVE usa la duracion promedio real de un evento, Chavez et al. 2019
  // (166 dias) -- una floracion tarda mas en apagarse que en prender.
  const tasa = (objetivo >= state.floracion)
    ? 1/(90*TICKS_POR_DIA)
    : 1/(DURACION_FLORACION_DIAS*TICKS_POR_DIA);
  state.floracion = clamp(state.floracion + (objetivo-state.floracion)*tasa, 0, 0.9);
  state.sueloDesnudo = clamp(1-state.floracion, 0, 1);
  const velocidadFloracion = Math.abs(state.floracion-floracionAntes);

  // Gyriosomus: rezago real de ~1 mes tras el pico de floracion (H4, hallazgo
  // propio de Cosmoclima, h4_rezago_gyriosomus.md) -- se arrastra desde un
  // buffer historico de floracion, y NO alimenta el albedo ni la temperatura:
  // mismo principio que powerLive/PTC (lo que se mide no es lo que regula).
  state.floracionHistorial.push(state.floracion);
  const CAP_DIAS = 95;
  if(state.floracionHistorial.length > CAP_DIAS*TICKS_POR_DIA) state.floracionHistorial.shift();
  const ticksRezago = Math.round(state.rezagoGyriosomus*TICKS_POR_DIA);
  const idx = state.floracionHistorial.length-1-ticksRezago;
  const objetivoGyriosomus = idx>=0 ? state.floracionHistorial[idx] : 0;
  state.gyriosomus = clamp(state.gyriosomus + (objetivoGyriosomus-state.gyriosomus)*0.05, 0, 0.9);

  const albedo = state.sueloDesnudo*state.albedoSueloDesnudo + state.floracion*state.albedoFloracionPlena;
  const absorbed = lum*(1-albedo);
  // Regulación interglacial (ver KAPPA_REGULACION_INTERGLACIAL más arriba)
  // -- se resta DESPUÉS del cálculo de albedo/Stefan-Boltzmann, no lo
  // reemplaza: el efecto de albedo real (chico, calienta) sigue existiendo
  // tal cual está medido, la regulación (grande, enfría) es un mecanismo
  // real ADICIONAL que antes faltaba por completo.
  const targetTf = temperaturaPlanetariaReal(absorbed) - state.floracion*KAPPA_REGULACION_INTERGLACIAL;
  // Instrumentación de SOLO LECTURA (11-ago-2026) -- targetTf y su versión
  // sin el término de regulación quedan guardadas para poder diagnosticar
  // A_sys_env desde afuera (investigar_asysenv.js) sin recalcular el albedo
  // ni la luminosidad efectiva por fuera del motor. No las lee la física.
  state.targetTf = targetTf;
  state.targetTfSinRegulacion = targetTf + state.floracion*KAPPA_REGULACION_INTERGLACIAL;
  return {albedo, targetTf, velocidadFloracion};
}

// --- función: getDayNightTemp ---
function getDayNightTemp(hour,minT,maxT){let lo=minT===undefined?state.minTemp:minT,hi=maxT===undefined?state.maxTemp:maxT;if(lo>=hi){const m=(lo+hi)/2;lo=m-0.05;hi=m+0.05;}const phase=(hour/24)*Math.PI*2;const normalized=(Math.sin(phase-Math.PI/2)+1)/2;return lo+normalized*(hi-lo)}

// --- función: seasonFactor ---
function seasonFactor(){
  // 0 en pleno invierno, 1 en pleno verano
  const fase=(state.tick*state.seasonSpeed)%1;
  return {fase, factor:(Math.sin(fase*Math.PI*2-Math.PI/2)+1)/2};
}

// --- función: seasonLabel ---
function seasonLabel(fase){
  if(fase<0.25) return 'Invierno';
  if(fase<0.5)  return 'Primavera';
  if(fase<0.75) return 'Verano';
  return 'Otoño';
}

// --- función: computeLFandErr ---
function computeLFandErr(velocidadFloracion){
  const viabilidadReal=clamp(state.A_sys_env,0,1);
  const senalLF = (PTC_REEMPLAZO_MODO==='B')
    ? 4*state.floracion*(1-state.floracion)
    : clamp(velocidadFloracion/VELOCIDAD_FLORACION_MAX_TEORICA, 0, 1);
  const targetPower=clamp(senalLF*viabilidadReal*HCFG.hi, 0.05, HCFG.hi);
  state.powerLive=lerp(state.powerLive,targetPower,0.08);

  // MULTIPLICIDAD DE ATRACTORES (no es LF declarativa: sin R3 no hay LF genuina).
  const deviation=Math.abs(state.powerLive-state.powerBase);
  const inertiaPenalty=Math.exp(-deviation*4);
  state.mult=clamp(deviation*(1-inertiaPenalty),0,1);
  // CORRECCIÓN 1 (11-ago-2026, ronda 13) -- QUITAR LA "V" DE LF.
  // Diagnóstico medido (motor/investigar_ratios_cuadrante.js): state.mult es
  // |powerLive - powerBase|, o sea la DISTANCIA a la posición de un control
  // deslizante de la interfaz (`powerBase`, "Consigna base del operador",
  // 0.47 de fábrica -- su propia ayuda en pantalla dice "es el centro, no el
  // máximo"). Al ser valor absoluto es una V: alejarse hacia arriba y hacia
  // abajo puntúan igual, y la dirección se pierde. Resultado medido sobre los
  // 62 años: en MEGASEQUÍA la señal cae al piso (~0.05) => distancia ~0.40 =>
  // LF crudo 0.263; en años de FLORACIÓN documentada la señal sube a ~0.80 =>
  // distancia ~0.33 => LF crudo 0.156. El instrumento premiaba el desierto
  // MUERTO por sobre el desierto FLORIDO, casi al doble. Eso explicaba que en
  // megasequía CIERRE cayera de 40% a 10.7% y SELVA_HOSTIL subiera a 49.4%,
  // justo al revés de la definición de Alexis ("Cierre... el sistema se
  // estabilizó sin cambios, punto de equilibrio sin cambios").
  // La corrección: LF es la SEÑAL misma -- la amplitud del espacio de
  // alternativas disponible (O-N7.4: "LF > 0 ⇒ ∃(Ri,Rj) tales que el sistema
  // puede seleccionar entre ellos"), no su desviación respecto de un slider
  // del operador. Se usa la LF ESTRUCTURAL (latente) de O-N13.8, sin modular
  // por A_sys_env, a propósito: si LF llevara A_sys_env dentro, los dos ejes
  // del cuadrante compartirían factor y el "Y" de clasificarCierre() dejaría
  // de ser una condición independiente.
  // state.mult queda calculado (no se borra) por trazabilidad del diagnóstico.
  state.LF = LF_SIN_V ? clamp(senalLF,0,1) : state.mult; // eje del cuadrante: Libertad Funcional
  state.err_exp=state.externalStress;
  // e_R (state.err) YA NO se calcula acá -- pasó a semanal real, ver
  // actualizarViabilidadSemanal() más abajo (10-ago-2026, Alexis: "para una
  // planta la variación día noche no es tan importante como la mensual",
  // luego subido a semanal en la ronda 5).
  // state._A_prev queda declarado por compatibilidad pero ya no se usa.
}

// --- función: semanaDelAnioReal ---
function semanaDelAnioReal(dia){ return Math.floor((dia % DIAS_POR_ANIO_CAL) / 7); }

// --- función: estacionAustralReal ---
function estacionAustralReal(mes){ // mes 0-based (0=enero), calendario REAL -- no seasonFactor() sintético
  if(mes===11||mes===0||mes===1) return 'Verano';
  if(mes>=2&&mes<=4) return 'Otoño';
  if(mes>=5&&mes<=7) return 'Invierno';
  return 'Primavera';
}

// --- sentencia: let _ultimaSemanaViabilidad=null, _sumCo... ---
let _ultimaSemanaViabilidad=null, _sumCouplingSemana=0, _nTicksSemanaViab=0, _A_sys_env_semanaAnterior=null;

// --- función: actualizarViabilidadSemanal ---
function actualizarViabilidadSemanal(dia, Tf, ref){
  const coupling=computeCoupling(Tf, ref);
  const f=fechaDesdeDiaCalendario(dia), claveSemana=f.anio+'-'+semanaDelAnioReal(dia);
  if(_ultimaSemanaViabilidad===null){
    // primer tick de la corrida: arranca el acumulador, no publica nada
    // todavía (A_sys_env queda en lo que traía el reset inicial) hasta que
    // se complete la primera semana real -- mismo espíritu que el
    // asentamiento térmico de 60 días que ya usa calcularDistribucionRegimen().
    _ultimaSemanaViabilidad=claveSemana; _sumCouplingSemana=coupling; _nTicksSemanaViab=1;
    return;
  }
  if(claveSemana!==_ultimaSemanaViabilidad){
    const promedioSemanaQueTermina=_sumCouplingSemana/Math.max(1,_nTicksSemanaViab);
    // e_R = -ΔA_sys_env (O-N4.1). El canon lo usa siempre en valor absoluto:
    // |e_R| en C-N2.8.5, O-N4.2 y C-N2.8.8. El max(0,...) anterior descartaba
    // las semanas en que el acoplamiento MEJORA y las anotaba como cero, lo que
    // dejaba e_R con mediana 0 -- ver el bloque ERR_ABSOLUTO más arriba.
    const _deltaA = promedioSemanaQueTermina - _A_sys_env_semanaAnterior;
    state.err=(_A_sys_env_semanaAnterior===null)?0:(ERR_ABSOLUTO?Math.abs(_deltaA):Math.max(0,-_deltaA));
    state.A_sys_env=promedioSemanaQueTermina;
    state.estacionAustralReal=estacionAustralReal(f.mes);
    _A_sys_env_semanaAnterior=promedioSemanaQueTermina;
    _ultimaSemanaViabilidad=claveSemana; _sumCouplingSemana=coupling; _nTicksSemanaViab=1;
  } else {
    _sumCouplingSemana+=coupling; _nTicksSemanaViab++;
    // A_sys_env/err quedan FIJOS dentro de la semana -- no se tocan acá.
  }
}

// --- sentencia: let _ultimaSemanaActivacion=null, _sumLF... ---
let _ultimaSemanaActivacion=null, _sumLFSemana=0, _sumDeltaSemana=0, _nTicksSemana=0, _LF_semanaAnterior=null, _delta_semanaAnterior=null;

// --- función: actualizarActivacionSemanal ---
function actualizarActivacionSemanal(dia){
  // LF/Δ_struct crudos de ESTE tick -- computeLFandErr()/computeDeltaStruct()
  // ya los dejaron en state.LF/state.deltaStruct antes de llegar acá (ambas
  // ramas de pasoFisica los calculan justo antes de llamar esta función).
  const lfCrudo=state.LF, deltaCrudo=state.deltaStruct;
  const f=fechaDesdeDiaCalendario(dia), claveSemana=f.anio+'-'+semanaDelAnioReal(dia);
  if(_ultimaSemanaActivacion===null){
    // primer tick de la corrida: arranca el acumulador, no publica nada
    // todavía -- mismo espíritu que actualizarViabilidadSemanal().
    _ultimaSemanaActivacion=claveSemana; _sumLFSemana=lfCrudo; _sumDeltaSemana=deltaCrudo; _nTicksSemana=1;
    return;
  }
  if(claveSemana!==_ultimaSemanaActivacion){
    state.LF=_sumLFSemana/Math.max(1,_nTicksSemana);
    state.deltaStruct=_sumDeltaSemana/Math.max(1,_nTicksSemana);
    _LF_semanaAnterior=state.LF; _delta_semanaAnterior=state.deltaStruct;
    _ultimaSemanaActivacion=claveSemana; _sumLFSemana=lfCrudo; _sumDeltaSemana=deltaCrudo; _nTicksSemana=1;
  } else {
    _sumLFSemana+=lfCrudo; _sumDeltaSemana+=deltaCrudo; _nTicksSemana++;
    // LF/Δ_struct quedan FIJOS dentro de la semana -- se restauran al valor
    // ya publicado (el crudo de este tick no debe filtrarse a
    // state.LF/state.deltaStruct, que son los que usa clasificarCierre()).
    if(_LF_semanaAnterior!==null){ state.LF=_LF_semanaAnterior; state.deltaStruct=_delta_semanaAnterior; }
  }
}

// --- sentencia: const DAY_NIGHT_WIDTH = 6;... ---
const DAY_NIGHT_WIDTH = 6;

// --- función: applyDayNightCycle ---
function applyDayNightCycle(){
  const cycleHour=(state.tick*state.dayNightSpeed)%24;
  // Estación: luminosidad Y temperatura ambiente se mueven juntas con el
  // "año". seasonEnvWinter/Summer son ahora temperaturas ABSOLUTAS (no un
  // corrimiento) — sin estaciones, se usa el punto medio entre ambas como
  // centro fijo del vaivén diario.
  let luminosidadEf=state.luminosity, centerEf=(state.seasonEnvWinter+state.seasonEnvSummer)/2;
  if(state.seasonMode){
    const {fase, factor}=seasonFactor();
    state.seasonFase=fase; state.seasonLabel=seasonLabel(fase);
    luminosidadEf=clamp(state.luminosity+lerp(state.seasonLumWinter,state.seasonLumSummer,factor), 0.3, 1.6);
    centerEf=lerp(state.seasonEnvWinter,state.seasonEnvSummer,factor);
  }
  let minEf=centerEf-DAY_NIGHT_WIDTH/2, maxEf=centerEf+DAY_NIGHT_WIDTH/2;
  // TEMPERATURA REAL REEMPLAZA EL VAIVÉN SINTÉTICO (10-ago-2026, ronda 6) --
  // auditoría a pedido de Alexis encontró que "activación" (LF) depende
  // solo de Tf, y Tf mezclaba lluvia real con un vaivén día/noche+estación
  // INVENTADO -- mientras que TEMPERATURA_DIARIA_ZHCS (línea ~1132, real,
  // estación Huintil/NASA POWER, 1981-2026) ya estaba cargada en este mismo
  // archivo pero SOLO para un gráfico de comparación, sin tocar la física
  // ("en un planeta real hay múltiples variables operando juntas, eso es
  // lo que tenemos que emular a partir de los datos reales que ya
  // tenemos"). Cuando hay dato real para EL DÍA CALENDARIO de hoy, min/max
  // reales reemplazan el centro/ancho sintéticos -- la FORMA sinusoidal
  // del ciclo día/noche (getDayNightTemp) no cambia, solo de dónde salen
  // el centro y la amplitud (mismo patrón que ya usa la lluvia: el dato
  // real reemplaza la cantidad, no la forma del modelo). Chequeo con
  // Number.isFinite en AMBOS campos, no solo que el objeto exista -- 3 de
  // los 16.657 registros tienen tmax/tmin en null, que si no se filtra se
  // convierte en 0°C silencioso por coerción de JS (sin error, sin NaN).
  // Cobertura real: 1981-01-01 a 2026-08-09 -- fuera de ese rango (1966-
  // 1980 y 2026-08-10 en adelante, ~24% de los 62 años) sigue el vaivén
  // sintético de arriba, sin cambios -- brecha real de datos, no se inventa.
  const _tempReal = (typeof TEMPERATURA_DIARIA_ZHCS!=='undefined')
    ? TEMPERATURA_DIARIA_ZHCS[claveFechaDiaria(diaCalendarioActual())] : undefined;
  const _hayTempReal = !!(_tempReal && Number.isFinite(_tempReal.tmin) && Number.isFinite(_tempReal.tmax));
  if(_hayTempReal){ minEf=_tempReal.tmin; maxEf=_tempReal.tmax; }
  state.coberturaTempReal = _hayTempReal;
  state.minTemp=minEf; state.maxTemp=maxEf; // se guardan para historial/CSV
  const envTemp=getDayNightTemp(cycleHour, minEf, maxEf);
  state.envTemp=envTemp;
  state.envDrift=envTemp-state.Tf;
  state.externalStress=Math.abs(state.envDrift)/Math.max(1,maxEf-minEf);
  const floracionData=computeFloracion(luminosidadEf);
  computeLFandErr(floracionData.velocidadFloracion);
  // La floración regula Tf — powerLive ya NO empuja la temperatura (v7.8):
  // el sensor/PTC mide, no calienta. Ver nota en pasoFisica().
  const thermalDrive=0.46*(floracionData.targetTf-state.Tf);
  const envForce=(envTemp-state.Tf);
  const damping=0.09+(1-state.beta)*0.65;
  const stochastic=(rngTf()-0.5)*state.noise*10;
  state.Tf=state.Tf+thermalDrive*0.12+envForce*0.12-damping*(state.Tf-state.tOpt)*0.05+stochastic;
  state.Th=lerp(state.Th,state.Tf+0.9+0.4*Math.sin(cycleHour/24*Math.PI*2),0.08);
  state.Tc=lerp(state.Tc,state.Tf+0.4,0.05);
  state.delta=state.Th-state.Tf;
  evolveField(floracionData.albedo);
  state.deltaStruct=computeDeltaStruct(field);
  actualizarActivacionSemanal(diaCalendarioActual());
  actualizarViabilidadSemanal(diaCalendarioActual(), state.Tf, lerp(envTemp,floracionData.targetTf,0.5));
  state.abioticTf=abioticTf(luminosidadEf);
  state.bioticTf=state.Tf;
  state.bioticFootprint=Math.abs(state.Tf-state.abioticTf);
  updateBehavioralEntropy();
  state.LF_exp=clamp(Math.abs(state.powerLive-state.powerBase),0,1);
  // BLOQUE 3 — Lambda cosmosemiótica unificada
  state.Lambda=(state.deltaStruct*state.LF)/Math.max(state.err,1e-6)*state.A_sys_env;
  state.Lambda_exp=state.Lambda;
  state.fertileScore=clamp(state.LF*(0.55+state.powerLive*0.25),0,1);
  const rr=classifyRegime(); state.regime=rr[0]; state.action=rr[1];
}

// --- sentencia: let _ultimoAnioLluvia=-1;... ---
let _ultimoAnioLluvia=-1;

// --- sentencia: let _ultimoDiaLluvia=-1;... ---
let _ultimoDiaLluvia=-1;

// --- sentencia: let _ultimoMesLluvia=null;... ---
let _ultimoMesLluvia=null;

// --- función: refrescarLluviaSiCambio ---
function refrescarLluviaSiCambio(dia){
  if(enTramoLluviaDiaria(dia)){
    if(dia!==_ultimoDiaLluvia){ _ultimoDiaLluvia=dia; actualizarLluviaDesdeCalendarioDiario(dia); }
  } else {
    const f=fechaDesdeDiaCalendario(dia), claveMes=f.anio+'-'+f.mes;
    if(claveMes!==_ultimoMesLluvia){ _ultimoMesLluvia=claveMes; actualizarLluviaDesdeCalendarioMensual(dia); }
  }
}

// --- función: pasoFisica ---
function pasoFisica(registrar){
  if(registrar===undefined) registrar=true; // false: calcularDistribucionRegimen() -- se salta pushHistory() (shift() O(n) sobre millones de ticks sería carísimo), la física real no cambia en nada
  refrescarLluviaSiCambio(diaCalendarioActual());
  if(state.dayNightMode){
    applyDayNightCycle();
  } else {
    const floracionData=computeFloracion();
    computeLFandErr(floracionData.velocidadFloracion);
    // La floración regula Tf: solo su albedo empuja la temperatura del
    // planeta (He et al. 2017). Hasta v7.7 un término 8.2*powerLive sumaba
    // el empuje del PTC/Peltier directamente sobre Tf, heredado del diseño
    // "Pastor del Borde" (v1.5.4): ahí el sensor SÍ era parte del lazo de
    // control. En este experimento powerLive es solo a_t, la conducta que se
    // MIDE (H(a_t)=κ_H) — quien regula la temperatura es la floración, no el
    // sensor. Retirado 30-jul-2026 a pedido de Alexis.
    const thermalDrive=0.46*(floracionData.targetTf-state.Tf);
    const damping=0.09+(1-state.beta)*0.65;
    const stochastic=(rngTf()-0.5)*state.noise*14;
    state.Tf=state.Tf+thermalDrive*0.12-damping*(state.Tf-state.tOpt)*0.05+stochastic;
    const edgeBias=(state.floracion-state.gyriosomus)*4.2;
    state.Tc=lerp(state.Tc,state.Tf+edgeBias*0.18,0.12);
    state.Th=lerp(state.Th,state.Tf+0.65+state.powerLive*1.8+edgeBias*0.32,0.10);
    state.delta=state.Th-state.Tf;
    evolveField(floracionData.albedo);
    state.deltaStruct=computeDeltaStruct(field);
    // v7.12 — unificado con applyDayNightCycle(): sin Día/Noche no hay ciclo
    // externo que computar, pero el "entorno" de referencia para A_sys_env
    // tiene que existir igual (antes quedaba con el envTemp viejo, sin
    // sentido en este modo). Se usa el punto medio Invierno/Verano, la misma
    // línea base que applyDayNightCycle() usa cuando Estaciones está apagado.
    state.envTemp=(state.seasonEnvWinter+state.seasonEnvSummer)/2;
    actualizarActivacionSemanal(diaCalendarioActual());
    actualizarViabilidadSemanal(diaCalendarioActual(), state.Tf, lerp(state.envTemp,floracionData.targetTf,0.5));
    state.abioticTf=abioticTf();
    state.bioticTf=state.Tf;
    state.bioticFootprint=Math.abs(state.Tf-state.abioticTf);
    updateBehavioralEntropy();
    state.LF_exp=clamp(Math.abs(state.powerLive-state.powerBase),0,1);
    // BLOQUE 3 — Lambda cosmosemiótica unificada
    state.Lambda=(state.deltaStruct*state.LF)/Math.max(state.err,1e-6)*state.A_sys_env;
    state.Lambda_exp=state.Lambda;
    // v7.12 — unificado con applyDayNightCycle(): tenía una fórmula propia
    // (con delta/Lambda) distinta a la de ese modo, sin razón declarada —
    // ahora es la misma fórmula en ambos modos.
    state.fertileScore=clamp(state.LF*(0.55+state.powerLive*0.25),0,1);
    const rr=classifyRegime(); state.regime=rr[0]; state.action=rr[1];
  }
  if(registrar) pushHistory();
  state.step+=state.dt;state.tick+=1;
}

// --- sentencia: const PLUVIO_ANIO_INICIO = ANIO_CERO;... ---
const PLUVIO_ANIO_INICIO = ANIO_CERO;

// --- sentencia: const PLUVIO_ANIO_FIN = ANIO_CERO + ANIO... ---
const PLUVIO_ANIO_FIN = ANIO_CERO + ANIOS_TOTALES_CAL - 1;

// --- función: valorMesReal ---
function valorMesReal(anio, mes){
  const clave = anio + '-' + String(mes+1).padStart(2,'0');
  const v = PLUVIOSIDAD_MENSUAL[clave];
  return (v === null || v === undefined) ? null : v;
}

// --- función: picoMensualAnio ---
function picoMensualAnio(anio){
  let max = null;
  for (let mes=0; mes<12; mes++) {
    const v = valorMesReal(anio, mes);
    if (v !== null && (max === null || v > max)) max = v;
  }
  return max;
}

// --- función: diaDesdeAnio ---
function diaDesdeAnio(anio, diaDelAnio){ return (anio-ANIO_CERO)*DIAS_POR_ANIO_CAL + (diaDelAnio||0); }


module.exports = {
  state, pasoFisica, clasificarCierre, classifyRegime,
  // field se REASIGNA dentro de evolveField()/resetField() (no se muta en
  // el mismo array) -- exportarlo como valor directo quedaría obsoleto tras
  // el primer tick. Getter para siempre devolver la referencia viva.
  get field() { return field; },
  diaCalendarioActual, fechaDesdeDiaCalendario, formatearFechaCalendario,
  computeFloracion, resetField, mulberry32, claveSemilla,
  get KAPPA_V() { return KAPPA_V; }, set KAPPA_V(v) { KAPPA_V = v; },
  get KAPPA_O() { return KAPPA_O; }, set KAPPA_O(v) { KAPPA_O = v; },
  get KAPPA_LF() { return KAPPA_LF; }, set KAPPA_LF(v) { KAPPA_LF = v; },
  get KAPPA_DELTA() { return KAPPA_DELTA; }, set KAPPA_DELTA(v) { KAPPA_DELTA = v; },
  get KAPPA_LF_POR_SEMANA() { return KAPPA_LF_POR_SEMANA; }, set KAPPA_LF_POR_SEMANA(v) { KAPPA_LF_POR_SEMANA = v; },
  get KAPPA_DELTA_POR_SEMANA() { return KAPPA_DELTA_POR_SEMANA; }, set KAPPA_DELTA_POR_SEMANA(v) { KAPPA_DELTA_POR_SEMANA = v; },
  get KAPPA_V_POR_SEMANA() { return KAPPA_V_POR_SEMANA; }, set KAPPA_V_POR_SEMANA(v) { KAPPA_V_POR_SEMANA = v; },
  get KAPPA_O_POR_SEMANA() { return KAPPA_O_POR_SEMANA; }, set KAPPA_O_POR_SEMANA(v) { KAPPA_O_POR_SEMANA = v; },
  get PTC_REEMPLAZO_MODO() { return PTC_REEMPLAZO_MODO; }, set PTC_REEMPLAZO_MODO(v) { PTC_REEMPLAZO_MODO = v; },
  get LF_SIN_V() { return LF_SIN_V; }, set LF_SIN_V(v) { LF_SIN_V = v; },
  get KAPPA_CANONICOS() { return KAPPA_CANONICOS; }, set KAPPA_CANONICOS(v) { KAPPA_CANONICOS = v; },
  get KAPPA_LF_INFIMO() { return KAPPA_LF_INFIMO; }, set KAPPA_LF_INFIMO(v) { KAPPA_LF_INFIMO = v; },
  get KAPPA_DELTA_INFIMO() { return KAPPA_DELTA_INFIMO; }, set KAPPA_DELTA_INFIMO(v) { KAPPA_DELTA_INFIMO = v; },
  get ERR_ABSOLUTO() { return ERR_ABSOLUTO; }, set ERR_ABSOLUTO(v) { ERR_ABSOLUTO = v; },
  get ERR_COTA_INFERIOR() { return ERR_COTA_INFERIOR; }, set ERR_COTA_INFERIOR(v) { ERR_COTA_INFERIOR = v; },
  get KAPPA_DELTA_CANONICO() { return KAPPA_DELTA_CANONICO; }, set KAPPA_DELTA_CANONICO(v) { KAPPA_DELTA_CANONICO = v; },
  TICKS_POR_DIA, ANIO_CERO, DIAS_POR_ANIO_CAL, ANIOS_TOTALES_CAL,
  TOPE_DIA_CALENDARIO, PLUVIOSIDAD_MENSUAL,
  set rngTf(fn) { rngTf = fn; }, get rngTf() { return rngTf; },
  set rngEco(fn) { rngEco = fn; }, get rngEco() { return rngEco; },
  resetBuffers() { aBuf = []; noiseEchoBuf = []; satBuf = []; },
};
